"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["31977"],{48582(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.agregado_sobre_fato_que_nao_eh_campo_de_grupo","status":422,"titulo":"O agregado resume fato declarado de membro de grupo"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.agregado_sobre_fato_que_nao_eh_campo_de_grupo","requisitos":["UNI-REQ-0143","UNI-REQ-0146"],"oQueAconteceu":["O administrador cadastrou um fato que resume respostas de grupo (`POST /api/configuracao/admin/fatos-candidato/agregados`) sobre um fato que existe no cat\xe1logo, mas que n\xe3o \xe9 um fato declarado de membro de grupo. Esse fato re\xfane as respostas de cada membro de um grupo repet\xedvel, como a composi\xe7\xe3o familiar (UNI-REQ-0146). Um fato derivado, um fato de integra\xe7\xe3o e um fato declarado com escopo `CANDIDATO`, que o candidato responde uma \xfanica vez, n\xe3o t\xeam respostas por membro para resumir.","A recusa vem na lista `errors` da resposta, com `field` igual a `fatoDeMembro`. A mensagem descreve a regra sem repetir o c\xf3digo do fato. Nada \xe9 gravado."],"comoResolver":["Escolha como fato de membro um fato declarado com escopo `MEMBRO_GRUPO`. Se o dado ainda n\xe3o \xe9 coletado por membro, cadastre um fato declarado com esse escopo (`POST /api/configuracao/admin/fatos-candidato`) e use-o no resumo de grupo."],"ondeAparece":["Cadastro de um fato do cat\xe1logo que resume respostas de grupo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);